                    if len(line) > 1:
                        for pos in line:
                            idx = idx_map.get(pos)
                            if idx is not None:
                                lines_map[idx].update(line)

    # Compute Grundy value using memoization
    memo = {}

    def get_grundy(state_mask):
        if state_mask == 0:
            return 0
        if state_mask in memo:
            return memo[state_mask]

        reachable = set()

        # For each chocolate cell, find all moves
        for pos in range(n_cells):
            if (state_mask >> pos) & 1:
                for line in lines_map[pos]:
                    # Try removing each non-empty subset of this line
                    line_list = list(line)
                    l = len(line_list)
                    for start in range(l):
                        for end in range(start + 1, l + 1):
                            cells_to_remove = line_list[start:end]
                            new_mask = state_mask
                            for c in cells_to_remove:
                                new_mask &= ~(1 << c)
                            if new_mask:  # Must make at least one chocolate disappear
                                g = get_grundy(new_mask)
                                reachable.add(g)

        grundy_val = mex(list(reachable))
        memo[state_mask] = grundy_val
        return grundy_val

    # Initial state mask
    initial_mask = 0
    for r, c in chocolate_cells:
        initial_mask |= (1 << idx_map[(r, c)])

    xor_sum = get_grundy(initial_mask)

    if xor_sum != 0:
        return "Karlsson\n"
    else:
        return "Lillebror\n"
