import sys

def solution(input_str):
    parts = input_str.split()
    n = int(parts[0])
    w = int(parts[1])
    q = int(parts[2])
    x = [int(parts[i]) for i in range(3, 3+n)]
    queries = [int(parts[3+n+i]) for i in range(q)]

    if n == 1:
        return "\n".join(['0'] * len(queries))

    # Count how many adjacent pairs require k >= threshold to merge
    # For adjacent photos x[j] and x[j+1], the overlap length is w - |x[j] - x[j+1]|
    # They can share the same k flowers only if k <= w - |x[j] - x[j+1]|
    # So minimum k needed for merging is w - |diff|, but if |diff| >= w, they never merge

    # difftrs[k] = number of pairs that can merge when threshold >= k
    # A pair merges for threshold t if t <= w - |diff|
    # So difftrs[k] counts pairs with (w - |diff|) >= k, i.e., |diff| <= w - k

    # For each query k, cuts = (n-1) - (number of pairs that can merge with this k)
    # Or equivalently, cuts = (n-1) - difftrs[w - k] if k <= w, else (n-1) - difftrs[0]

    # Let's precompute: can_merge[t] = number of pairs where w - |diff| >= t
    # This means |diff| <= w - t, i.e., pairs are close enough

    diff_constraint = [0] * (w + 2)  # diff_constraint[d] = count of pairs with |diff| <= d

    for j in range(n - 1):
        diff = abs(x[j+1] - x[j])
        diff_constraint[diff] += 1

    # Compute prefix sums: prefix[d] = count of pairs with |diff| <= d
    prefix = [0] * (w + 2)
    for d in range(w + 1):
        prefix[d] = prefix[d-1] + diff_constraint[d] if d > 0 else diff_constraint[0]

    def count_mergeable(k):
        """Count pairs that can merge given truncation width k"""
        if k > w:
            return prefix[w]
        if k <= 0:
            return 0
        max_diff = w - k
        if max_diff < 0:
            return 0
        if max_diff > w:
            max_diff = w
        return prefix[max_diff]

    result = []
    for k in queries:
        if k > w:
            mergeable = count_mergeable(w)
        else:
            mergeable = count_mergeable(k)
        cuts = (n - 1) - mergeable
        result.append(str(cuts))

    return "\n".join(result)


