def solution(s):
    """
    Parse the arithmetic expression according to the given grammar and
    return the result modulo 10^9 + 7.

    Grammar rules:
    - <expression> ::= <term> | <expression> '+' <term>
    - <term> ::= <number> | <number> '-' <number> | <number> '(' <expression> ')'
    - <number> describes itself, or for "l-r" (l ≤ r) concatenates all integers from l to r
    - <number>(<expression>) repeats the expression, described by the number, n times
    """
    n = len(s)
    pos = [0]  # Using list to allow modification in nested functions

    def num_len(x):
        """Return the length of the string representation of x"""
        return len(str(x))

    def concat_range(l, r):
        """
        Concatenate all integers from l to r and compute the value mod MOD
        Returns (value, length)
        """
        if l > r:
            return 0, 0

        val, length = l, num_len(l)
        for i in range(l + 1, r + 1):
            ln = num_len(i)
            length += ln
            val = (val * pow(10, ln, MOD) + i) % MOD
        return val, length

    def replicate(val, length, count):
        """
        Repeat a value 'count' times (n concatenation)
        Returns (value, total_length)
        """
        if count == 0:
            return 0, 0
        if count == 1:
            return val % MOD, length

        shift = pow(10, length, MOD)
        result = val % MOD

        for _ in range(2, count + 1):
            result = (result * shift + val) % MOD

        total_length = length * count
        return result, total_length

    def parse_number():
        """
        Parse a number. It can be:
        - A simple integer like "8"
        - A range like "8-11" (concatenates 8, 9, 10, 11)
        - Handles the start of n(expression) by checking for '('
        """
        start = pos[0]

        while pos[0] < n and s[pos[0]].isdigit():
            pos[0] += 1

        if pos[0] == start:
            return 0, 0

        l_val = int(s[start:pos[0]])
        ln = num_len(l_val)

        # Check for range l-r
        if pos[0] < n and s[pos[0]] == '-':
            pos[0] += 1  # skip '-'
            end = pos[0]
            while pos[0] < n and s[pos[0]].isdigit():
                pos[0] += 1
            if pos[0] > end:
                r_val = int(s[end:pos[0]])
                return concat_range(l_val, r_val)

        # Check for repetition: n(expression)
        if pos[0] < n and s[pos[0]] == '(':
            pos[0] += 1  # skip '('
            inner_val, inner_length = parse_expr()
            if pos[0] < n and s[pos[0]] == ')':
                pos[0] += 1
            return replicate(l_val, inner_length, l_val)

        return l_val % MOD, ln

    def parse_term():
        """Parse a term"""
        return parse_number()

    def parse_expr():
        """Parse an expression (one or more terms separated by +)"""
        v, lv = parse_term()

