        """Check if (a,b) is a valid set score"""
        if a < 0 or b < 0:
            return False
        if a == b:
            return False

        winner = max(a, b)
        loser = min(a, b)

        # Must win by 2 points (except in deuce scenarios)
        if winner - loser < 2:
            return False

        # Normal sets: need >= 25, 5th set: need >= 15
        if winner < 25 and (a + b >= 50 or winner > 30):
            # Check if it could be a deuce scenario
            if winner < 25:
                return False
        if winner >= 25 and winner - loser >= 2:
            return True

        # Also allow cases like 25-23, 26-24, etc.
        if winner >= 25 and winner - loser >= 2:
            return True

        return winner >= 15  # For 5th set rule

    def can_form_valid_match(total_a, total_b, tie_a, tie_b, sets_planned):
        """Check if we can distribute points for given match outcome"""
        # Generate max 5 sets
        if sets_planned <= 0:
            return total_a == tie_a and total_b == tie_b

        # Greedy approach - try to form valid sets
        remaining_a = total_a if tie_a > 0 else tie_a
        remaining_b = total_b if tie_b > 0 else tie_b

        # Check if remaining can form valid points
        if sets_planned == 1:
            if remaining_a + remaining_b == 0:
                return True
            if remaining_a < 25 and remaining_a < 15:
                return False
            if remaining_b < 25 and remaining_b < 15:
                return False
            return True

        return True

    for i in range(1, m + 1):
        if i >= len(lines):
            continue

        try:
            parts = lines[i].split()
            if len(parts) < 2:
                continue
            a, b = int(parts[0]), int(parts[1])
