                if sets_a < 3 and sets_b < 3:
                    continue
                if sets_a + sets_b < 3:
                    continue
                if sets_a == sets_b:
                    continue

                # Calculate minimum possible points for this match
                min_a = 0
                min_b = 0
                max_a = a
                max_b = b

                for s in range(sets_a + sets_b):
                    min_a += 0
                    min_b += 25 if s < sets_b else 25

                if sets_a == 3:
                    if a < 70 or b > a:
                        continue
                if best is None:
                    best = (sets_a, sets_b)
                    # Generate sample set scores
                    set_scores = []
                    for s in range(sets_a):
                        set_scores.append("25:0")
                    for s in range(sets_b):
                        set_scores.append("0:25")
                    best_sets_output = " ".join(set_scores + ["25:24-2" if sets_a + sets_b > 3 else ""])

        if best:
