def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    if n == 0:
        return "0"

    def get_prime_factors(x):
        """Get all prime factors of x."""
        if x <= 1:
            return set()
        factors = set()
        d = 2
        while d * d <= x:
            if x % d == 0:
                factors.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            factors.add(x)
        return factors

    # Collect candidate primes from first and last few elements
    all_primes = set()
    params = [0, 1, 2] if n >= 3 else list(range(min(n, 3)))
    for i in params:
        for val in [arr[i], arr[i]-1, arr[i]+1]:
            all_primes.update(get_prime_factors(val))

    for i in range(max(0, n-3), n):
        for val in [arr[i], arr[i]-1, arr[i]+1]:
            all_primes.update(get_prime_factors(val))

    INF = float('inf')
    min_total_cost = INF

    for p in all_primes:
        fix_costs = []
        must_remove_positions = []
        fix_sum = 0

        for x in arr:
            fix_cost = INF
            if x % p == 0:
                fix_cost = 0
            elif (x - 1) % p == 0 or (x + 1) % p == 0:
                fix_cost = b
            else:
                must_remove_positions.append(len(fix_costs))
            fix_costs.append(fix_cost)

        if len(must_remove_positions) > 0:
            # Find range to cover all must-remove elements
            l_rem = min(must_remove_positions)
            r_rem = max(must_remove_positions)

            cost = a * (r_rem - l_rem + 1)
            for i in range(l_rem, r_rem + 1):
                pass  # These are removed

            for i, fc in enumerate(fix_costs):
                if i < l_rem or i > r_rem:
                    cost += fc

            min_total_cost = min(min_total_cost, cost)
        else:
            # Standard Kadane's for minimum subarray sum
            current = 0
            min_sum = 0
            for fc in fix_costs:
                w = a - fc
                current += w
                if current > 0:
                    current = 0
                min_sum = min(min_sum, current)

            cost = fix_sum + min_sum
            min_total_cost = min(min_total_cost, cost)

    return str(min_total_cost)

